import{_ as r,o as i,c as t,a5 as a}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"等待导航结果","description":"当使用 router link 组件时，Vue Router 会自动调用 router.push 来触发一次导航。虽然大多数链接的预期行为是将用户导航到一个新页面，但也有少数情况下用户将留在同一页面上： 用户已经位于他们正在尝试导航到的页面； 一个导航守卫通过调用 return。","frontmatter":{"title":"等待导航结果","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"当使用 router link 组件时，Vue Router 会自动调用 router.push 来触发一次导航。虽然大多数链接的预期行为是将用户导航到一个新页面，但也有少数情况下用户将留在同一页面上： 用户已经位于他们正在尝试导航到的页面； 一个导航守卫通过调用 return。","sidebarWeight":54,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/等待导航结果.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/等待导航结果.md","filePath":"posts/Vue系统教程/04-路由与状态管理/等待导航结果.md"}'),o={name:"posts/Vue系统教程/04-路由与状态管理/等待导航结果.md"};function u(s,e,l,n,p,d){return i(),t("div",null,[...e[0]||(e[0]=[a('<div><h1 id="等待导航结果" tabindex="-1">等待导航结果 <a class="header-anchor" href="#等待导航结果" aria-label="Permalink to &quot;等待导航结果&quot;">​</a></h1><blockquote><p>本节目标：理解“等待导航结果”的核心思路，并能把它用于实际开发或面试表达。 当使用 router-link 组件时，Vue Router 会自动调用 router.push 来触发一次导航。虽然大多数链接的预期行为是将用户导航到一个新页面，但也有少数情况下用户将留在同一页面上：</p></blockquote><ul><li>用户已经位于他们正在尝试导航到的页面；</li><li>一个导航守卫通过调用 return false 中断了这次导航；</li><li>当前的导航守卫还没有完成时，一个新的导航守卫会出现了；</li><li>一个导航守卫通过返回一个新的位置，重定向到其他地方 (例如，return &#39;/login&#39;)</li><li>一个导航守卫抛出了一个 Error；</li></ul><p>如果我们想在一个导航完成后做一些事情，我们需要一个在调用 router.push 后进行等待的方法。想象一下，我们有一个移动手机菜单，它允许我们进入不同的页面，而我们只想在导航到新页面后隐藏菜单，我们可能想这样做： router.push(&#39;/my-profile&#39;) this.isMenuOpen = false 但是这样做会马上关闭菜单，因为 导航是异步的，我们需要 await router.push 返回的 promise ： await router.push(&#39;/my-profile&#39;) this.isMenuOpen = false 现在，一旦导航完成，菜单就会关闭，但如果导航被阻止，它也会关闭。我们需要一种方法来检测我们是否真的改变了页面。</p><p><strong>检测导航故障</strong> 如果导航被阻止，导致用户停留在同一个页面上，由 router.push 返回的 Promise 的解析值将是 Navigation Failure。否则，它将是一个 falsy 值(通常是 undefined)。这样我们就可以区分我们导航是否离开了当前位置： const navigationResult = await router.push(&#39;/my-profile&#39;) if (navigationResult) { // 导航被阻止 } else { // 导航成功 (包括重新导航的情况) this.isMenuOpen = false } Navigation Failure 是带有一些额外属性的 Error 实例，这些属性为我们提供了足够的信息，让我们知道哪些导航被阻止了以及为什么被阻止了。要检查导航结果的性质，请使用 isNavigationFailure 函数： import { NavigationFailureType, isNavigationFailure } from &#39;vue-router&#39; // 试图离开未保存的编辑文本界面 const failure = await router.push(&#39;/articles/2&#39;) if (isNavigationFailure(failure, NavigationFailureType.aborted)) { // 给用户显示一个小通知 showToast(&#39;You have unsaved changes, discard and leave anyway?&#39;) }</p><p>TIP 如果你忽略第二个参数： isNavigationFailure(failure)，那么就只会检查这个 failure 是不是一个 Navigation Failure。</p><p><strong>鉴别导航故障</strong> 正如我们在一开始所说的，有不同的情况会导致导航的中止，所有这些情况都会导致不同的 Navigation Failure。它们可以用 isNavigationFailure 和 NavigationFailureType 来区分。总共有三种不同的类型：</p><ul><li>aborted：在导航守卫中返回 false 中断了本次导航。</li><li>cancelled： 在当前导航还没有完成之前又有了一个新的导航。比如，在等待导航守卫的过程中又调用了 router.push。</li><li>duplicated：导航被阻止，因为我们已经在目标位置了。</li></ul><p><strong>导航故障的属性</strong> 所有的导航失败都会暴露 to 和 from 属性，以反映失败导航的当前位置和目标位置： // 正在尝试访问 admin 页面 router.push(&#39;/admin&#39;).then(failure =&gt; { if (isNavigationFailure(failure, NavigationFailureType.redirected)) { failure.to.path // &#39;/admin&#39; failure.from.path // &#39;/&#39; } }) 在所有情况下，to 和 from 都是规范化的路由地址。</p><p><strong>检测重定向</strong> 当在导航守卫中返回一个新的位置时，我们会触发一个新的导航，覆盖正在进行的导航。与其他返回值不同的是，重定向不会阻止导航，而是创建一个新的导航。因此，通过读取路由地址中的 redirectedFrom 属性，对其进行不同的检查： await router.push(&#39;/my-profile&#39;) if (router.currentRoute.value.redirectedFrom) { // redirectedFrom 是解析出的路由地址，就像导航守卫中的 to和 from }</p></div>',1)])])}const g=r(o,[["render",u]]);export{c as __pageData,g as default};
